using System.Text.Json.Nodes;
using TouhouLastWorld;

internal sealed partial class RegressionSuite
{
    private void Scenario10()
    {
        pictureBreakSeed["picture"]!["picture_list"]![1]!["spec_actualize"] = 0;
        pictureBreakSeed["picture"]!["picture_list"]![2]!["spec_actualize"] = 0;
        pictureBreakSeed["picture"]!["picture_list"]![2]!["is_protection"] = 0;
        var pictureRecycleDirectory = directory + "-picture-recycle";
        var pictureRecycleServer = new OfflineServer(new JsonStateStore(pictureRecycleDirectory), pictureBreakSeed.ToJsonString(), "offline://resources/");
        pictureRecycleServer.Dispatch("game_init");
        pictureRecycleServer.Dispatch("login");
        var pictureRecycleRule = new LocalPictureRecycle([new(701, 71, 0, 1, [new(3, 0, 100), new(12, 72, 3)]), new(702, 71, 0, 0, [new(3, 0, 200), new(5, 0, 5), new(2, 0, 10)])], 10000, 10000, 9999);
        Check(pictureRecycleServer.Dispatch("picture_recycle", arguments: new(Ids: [701, 702], PictureRecycle: pictureRecycleRule with { GoldMax = 5100 })).Status == 409 && pictureRecycleServer.Dispatch("login").Body!["user"]!["picture"]!["picture_list"]!.AsArray().Count == 3, "recycle capacity failure preserves all equipment");
        Check(pictureRecycleServer.Dispatch("picture_recycle", arguments: new(Ids: [701, 702], PictureRecycle: pictureRecycleRule with { Entries = [pictureRecycleRule.Entries[0], pictureRecycleRule.Entries[1] with { Gains = [new(10, 99, 1)] }] })).Status == 503, "recycle rejects unsupported rewards before consuming equipment");
        var pictureRecycled = pictureRecycleServer.Dispatch("picture_recycle", arguments: new(Ids: [701, 702], PictureRecycle: pictureRecycleRule)).Body!;
        Check(pictureRecycled["gain_object_list"]!.AsArray().Count == 4 && pictureRecycled["gain_object_list"]![0]!["value"]!.GetValue<int>() == 300 && pictureRecycled["remove_user_picture_id_list"]!.AsArray().Count == 2 && pictureRecycled["user_update"]!["gold"]!.GetValue<int>() == 5300 && pictureRecycled["user_update"]!["phantasm_point"]!["points"]!.GetValue<int>() == 110 && pictureRecycled["user_update"]!["item"]!["item_list"]!.AsArray().Any(item => item!["item_id"]!.GetValue<int>() == 72 && item["num"]!.GetValue<int>() == 3) && pictureRecycled["user_update"]!["unit"]!["unit_list"]![0]!["equip_spellcard1_user_picture_id"]!.GetValue<long>() == 0, "recycle aggregates rewards, removes equipment and clears assignment");
        var pictureRecycleReload = new OfflineServer(new JsonStateStore(pictureRecycleDirectory), seed, "offline://resources/");
        pictureRecycleReload.Dispatch("game_init");
        pictureRecycleReload.Dispatch("login");
        Check(pictureRecycleReload.Dispatch("picture_recycle", arguments: new(Ids: [701, 702], PictureRecycle: pictureRecycleRule)).Status == 404 && pictureRecycleReload.Dispatch("login").Body!["user"]!["gold"]!.GetValue<int>() == 5300, "recycle persists and does not repeat rewards");
        Console.WriteLine("Passed 4 equipment recycle checks.");
        var lectureTrustSeed = JsonNode.Parse(seed)!;
        lectureTrustSeed["lecture_room"]!["unit"]!["unit_list"] = new JsonArray(new JsonObject { ["user_unit_id"] = rankMaterialId, ["put_trust_up_icon"] = 1 });
        lectureTrustSeed["_local_lecture_trust_rewards"] = new JsonArray(new JsonObject { ["user_unit_id"] = rankMaterialId, ["value"] = 10 });
        var lectureTrustDirectory = directory + "-lecture-trust";
        var lectureTrustServer = new OfflineServer(new JsonStateStore(lectureTrustDirectory), lectureTrustSeed.ToJsonString(), "offline://resources/");
        lectureTrustServer.Dispatch("game_init");
        lectureTrustServer.Dispatch("login");
        Check(lectureTrustServer.Dispatch("lecture_room_unit_trust_up", arguments: new(rankMaterialId, 5)).Status == 409 && lectureTrustServer.Dispatch("login").Body!["user"]!["unit"]!["unit_list"]![0]!["trust"]!.GetValue<int>() == 0, "trust capacity failure preserves pending reward and value");
        var lectureTrustReply = lectureTrustServer.Dispatch("lecture_room_unit_trust_up", arguments: new(rankMaterialId, 100)).Body!["user_update"]!;
        Check(lectureTrustReply["unit"]!["unit_list"]![0]!["trust"]!.GetValue<int>() == 10 && lectureTrustReply["lecture_room"]!["unit"]!["unit_list"]![0]!["put_trust_up_icon"]!.GetValue<int>() == 0, "trust receipt credits saved value and clears notification");
        var lectureTrustReload = new OfflineServer(new JsonStateStore(lectureTrustDirectory), seed, "offline://resources/");
        lectureTrustReload.Dispatch("game_init");
        lectureTrustReload.Dispatch("login");
        Check(lectureTrustReload.Dispatch("lecture_room_unit_trust_up", arguments: new(rankMaterialId, 100)).Status == 409 && lectureTrustReload.Dispatch("login").Body!["user"]!["unit"]!["unit_list"]![0]!["trust"]!.GetValue<int>() == 10, "trust reward cannot be claimed twice after reload");
        Console.WriteLine("Passed 3 lecture trust checks.");
        var relationSeed = JsonNode.Parse(seed)!;
        relationSeed["twitter_info"]!["is_related"] = 1;
        relationSeed["_local_twitter_user_id"] = "local-test-identity";
        relationDirectory = directory + "-local-relation";
        var relationServer = new OfflineServer(new JsonStateStore(relationDirectory), relationSeed.ToJsonString(), "offline://resources/");
        relationServer.Dispatch("game_init");
        relationServer.Dispatch("login");
        Check(relationServer.Dispatch("user_twitter_info_delete", arguments: new(Text: "")).Status == 400 && relationServer.Dispatch("user_twitter_info_delete", arguments: new(Text: "different")).Status == 409 && relationServer.Dispatch("login").Body!["user"]!["twitter_info"]!["is_related"]!.GetValue<int>() == 1, "local unlink rejects empty or mismatched identity without changing relation");
        Check(relationServer.Dispatch("user_twitter_info_delete", arguments: new(Text: "local-test-identity")).Body!["user_update"]!["twitter_info"]!["is_related"]!.GetValue<int>() == 0, "local unlink clears relation flag");
        relationReload = new OfflineServer(new JsonStateStore(relationDirectory), seed, "offline://resources/");
        relationReload.Dispatch("game_init");
        Check(relationReload.Dispatch("login").Body!["user"]!["twitter_info"]!["is_related"]!.GetValue<int>() == 0 && relationReload.Dispatch("user_twitter_info_delete", arguments: new(Text: "local-test-identity")).Status == 0, "local unlink persists and repeated clearing is harmless");
        Console.WriteLine("Passed 3 local relation checks.");
        var appleRelationSeed = JsonNode.Parse(seed)!;
        appleRelationSeed["apple_relation"] = 1;
        appleRelationSeed["google_relation"] = 1;
        var appleRelationDirectory = directory + "-apple-relation";
        var appleRelationServer = new OfflineServer(new JsonStateStore(appleRelationDirectory), appleRelationSeed.ToJsonString(), "offline://resources/");
        appleRelationServer.Dispatch("game_init");
        appleRelationServer.Dispatch("login");
        Check(appleRelationServer.Dispatch("user_apple_info_delete").Body!["user_update"]!["apple_relation"]!.GetValue<int>() == 0 && appleRelationServer.Dispatch("login").Body!["user"]!["google_relation"]!.GetValue<int>() == 1, "local Apple unlink clears only its own relation");
        var appleRelationReload = new OfflineServer(new JsonStateStore(appleRelationDirectory), seed, "offline://resources/");
        appleRelationReload.Dispatch("game_init");
        Check(appleRelationReload.Dispatch("login").Body!["user"]!["apple_relation"]!.GetValue<int>() == 0 && appleRelationReload.Dispatch("user_apple_info_delete").Status == 0, "local Apple unlink persists and is repeatable");
        Console.WriteLine("Passed 2 local Apple relation checks.");
        var googleRelationDirectory = directory + "-google-relation";
        var googleRelationServer = new OfflineServer(new JsonStateStore(googleRelationDirectory), appleRelationSeed.ToJsonString(), "offline://resources/");
        googleRelationServer.Dispatch("game_init");
        googleRelationServer.Dispatch("login");
        Check(googleRelationServer.Dispatch("user_google_info_delete").Body!["user_update"]!["google_relation"]!.GetValue<int>() == 0 && googleRelationServer.Dispatch("login").Body!["user"]!["apple_relation"]!.GetValue<int>() == 1, "local Google unlink clears only its own relation");
        var googleRelationReload = new OfflineServer(new JsonStateStore(googleRelationDirectory), seed, "offline://resources/");
        googleRelationReload.Dispatch("game_init");
        Check(googleRelationReload.Dispatch("login").Body!["user"]!["google_relation"]!.GetValue<int>() == 0 && googleRelationReload.Dispatch("user_google_info_delete").Status == 0, "local Google unlink persists and is repeatable");
        Console.WriteLine("Passed 2 local Google relation checks.");
        var replayStartServer = new OfflineServer(new JsonStateStore(directory + "-replay-start"), seed, "offline://resources/");
        replayStartServer.Dispatch("game_init");
        replayStartServer.Dispatch("login");
        Check(replayStartServer.Dispatch("auto_replay_start", arguments: new(Value: 0, ReplayMeasure: new(0, 1, 1))).Status == 400, "background replay rejects empty execution count");
        var replayStartBefore = replayStartServer.Dispatch("login").Body!["user"]!.ToJsonString();
        Check(replayStartServer.Dispatch("auto_replay_start", arguments: new(Value: 10, ReplayMeasure: new(0, 1, 1))).Body!["user_update"]!["auto_replay"]!["target_id"]!.GetValue<long>() == 0 && replayStartServer.Dispatch("login").Body!["user"]!.ToJsonString() == replayStartBefore, "unavailable background replay follows cancelled branch without changing state or charging");
        var activeReplaySeed = JsonNode.Parse(seed)!;
        activeReplaySeed["auto_replay"]!["target_id"] = 1L;
        var activeReplayServer = new OfflineServer(new JsonStateStore(directory + "-replay-active"), activeReplaySeed.ToJsonString(), "offline://resources/");
        activeReplayServer.Dispatch("game_init");
        activeReplayServer.Dispatch("login");
        Check(activeReplayServer.Dispatch("auto_replay_start", arguments: new(Value: 10, ReplayMeasure: new(0, 2, 1))).Status == 409 && activeReplayServer.Dispatch("login").Body!["user"]!["auto_replay"]!["target_id"]!.GetValue<long>() == 1, "background replay does not overwrite an existing task");
        Console.WriteLine("Passed 3 background replay boundary checks.");
        var exchangeSeed = JsonNode.Parse(seed)!;
        exchangeSeed["item"]!["item_list"] = new JsonArray(new JsonObject { ["item_id"] = 71, ["num"] = 10 });
        var exchangeDirectory = directory + "-item-exchange";
        var exchangeServer = new OfflineServer(new JsonStateStore(exchangeDirectory), exchangeSeed.ToJsonString(), "offline://resources/");
        exchangeServer.Dispatch("game_init");
        exchangeServer.Dispatch("login");
        var exchangeRule = new LocalItemExchange(1, 71, 3, 72, 100);
        Check(exchangeServer.Dispatch("item_exchange", arguments: new(1, 4, ItemExchange: exchangeRule)).Status == 409 && exchangeServer.Dispatch("item_exchange", arguments: new(1, 2, ItemExchange: exchangeRule with { Capacity = 1 })).Status == 409, "item exchange checks both cost and capacity before saving");
        var exchangeReply = exchangeServer.Dispatch("item_exchange", arguments: new(1, 2, ItemExchange: exchangeRule)).Body!["user_update"]!["item"]!["item_list"]!;
        Check(exchangeReply[0]!["num"]!.GetValue<int>() == 4 && exchangeReply[1]!["num"]!.GetValue<int>() == 2, "item exchange deducts multiplied cost and creates target inventory");
        var exchangeReload = new OfflineServer(new JsonStateStore(exchangeDirectory), seed, "offline://resources/");
        exchangeReload.Dispatch("game_init");
        exchangeReload.Dispatch("login");
        Check(exchangeReload.Dispatch("item_exchange", arguments: new(1, int.MaxValue, ItemExchange: exchangeRule)).Status == 409 && exchangeReload.Dispatch("item_exchange", arguments: new(1, 1, ItemExchange: exchangeRule)).Body!["user_update"]!["item"]!["item_list"]![1]!["num"]!.GetValue<int>() == 3, "item exchange persists, handles large quantities and accumulates existing target");
        Console.WriteLine("Passed 3 item exchange checks.");
        var applicationDirectory = directory + "-application";
        var applicationServer = new OfflineServer(new JsonStateStore(applicationDirectory), seed, "offline://resources/");
        applicationServer.Dispatch("game_init");
        applicationServer.Dispatch("login");
        Check(applicationServer.Dispatch("anniversary_info_update", arguments: new(Value: 0, Text: "local@example.invalid")).Status == 400 && applicationServer.Dispatch("anniversary_info_update", arguments: new(Value: 1, Text: "invalid")).Status == 400, "local application requires consent and a mail address");
        Check(applicationServer.Dispatch("anniversary_info_update", arguments: new(Value: 1, Text: " local@example.invalid ")).Body!["user_update"]!["anniversary_present"]!["applied"]!.GetValue<int>() == 1, "local application updates the display state");
        var applicationReload = new OfflineServer(new JsonStateStore(applicationDirectory), seed, "offline://resources/");
        applicationReload.Dispatch("game_init");
        applicationReload.Dispatch("login");
        Check(applicationReload.Dispatch("anniversary_info_get").Body!["mail_address"]!.GetValue<string>() == "local@example.invalid", "local application address persists and can be read");
        Console.WriteLine("Passed 3 local application checks.");
        Check(applicationReload.Dispatch("personal_info_update", arguments: new(ContactDetails: new("", "000", "Local", "000"))).Status == 400, "local contact details reject missing fields");
        Check(applicationReload.Dispatch("personal_info_update", arguments: new(ContactDetails: new("Sample", "000", "Local", "000"))).Body!["user_update"]!["figure_present"]!["applied"]!.GetValue<int>() == 1, "local contact details update the application state");
        var contactDetailsReload = new OfflineServer(new JsonStateStore(applicationDirectory), seed, "offline://resources/");
        contactDetailsReload.Dispatch("game_init");
        contactDetailsReload.Dispatch("login");
        Check(contactDetailsReload.Dispatch("personal_info_get").Body!["user_name"]!.GetValue<string>() == "Sample" && contactDetailsReload.Dispatch("anniversary_info_get").Body!["mail_address"]!.GetValue<string>() == "local@example.invalid", "local contact details persist independently of mail details");
        Console.WriteLine("Passed 3 local contact detail checks.");
        var dispatchStartSeed = JsonNode.Parse(seed)!;
        var dispatchMemberId = dispatchStartSeed["unit"]!["unit_list"]![0]!["user_unit_id"]!.GetValue<long>();
        var dispatchMemberType = dispatchStartSeed["unit"]!["unit_list"]![0]!["unit_id"]!.GetValue<int>();
        dispatchStartSeed["_local_dispatch_offers"] = new JsonArray(new JsonObject { ["user_dispatch_id"] = 701L, ["dispatch_id"] = 7, ["end_time"] = "", ["appearance_finish_time"] = "", ["user_unit_id_list"] = new JsonArray() });
        var dispatchStartDirectory = directory + "-dispatch-start";
        var dispatchStartServer = new OfflineServer(new JsonStateStore(dispatchStartDirectory), dispatchStartSeed.ToJsonString(), "offline://resources/");
        dispatchStartServer.Dispatch("game_init");
        dispatchStartServer.Dispatch("login");
        var dispatchStartRule = new LocalDispatchStart(7, 600, 10, 1, 1, 10, 1, new[] { new LocalDispatchMember(dispatchMemberId, dispatchMemberType, 10, true) });
        var dispatchStartArgs = new RequestDraft(701, Ids: new[] { dispatchMemberId }, DispatchStart: dispatchStartRule);
        Check(dispatchStartServer.Dispatch("dispatch_start", arguments: dispatchStartArgs with { EntityId = 702 }).Status == 404 && dispatchStartServer.Dispatch("dispatch_start", arguments: dispatchStartArgs with { DispatchStart = dispatchStartRule with { RequiredLevel = 11 } }).Status == 409 && dispatchStartServer.Dispatch("dispatch_start", arguments: dispatchStartArgs with { DispatchStart = dispatchStartRule with { Cost = int.MaxValue } }).Status == 409, "dispatch start rejects missing offers, unmet levels and insufficient points without mutation");
        var dispatchStartReply = dispatchStartServer.Dispatch("dispatch_start", arguments: dispatchStartArgs).Body!["user_update"]!;
        Check(dispatchStartReply["phantasm_point"]!["points"]!.GetValue<int>() == 90 && dispatchStartReply["dispatch"]!["dispatch_list"]![0]!["user_unit_id_list"]![0]!.GetValue<long>() == dispatchMemberId && DateTime.Parse(dispatchStartReply["dispatch"]!["dispatch_list"]![0]!["end_time"]!.GetValue<string>()) > DateTime.UtcNow.AddMinutes(9), "dispatch start deducts cost and records members and finish time");
        var dispatchStartReload = new OfflineServer(new JsonStateStore(dispatchStartDirectory), seed, "offline://resources/");
        dispatchStartReload.Dispatch("game_init");
        dispatchStartReload.Dispatch("login");
        Check(dispatchStartReload.Dispatch("dispatch_start", arguments: dispatchStartArgs).Status == 409 && dispatchStartReload.Dispatch("get_dispatch_list").Body!["dispatch_list"]![0]!["user_unit_id_list"]!.AsArray().Count == 1, "dispatch start persists and cannot charge twice");
        dispatchStartReload.Dispatch("dispatch_cancel", arguments: new(701));
        Check(dispatchStartReload.Dispatch("get_dispatch_list").Body!["dispatch_list"]![0]!["user_unit_id_list"]!.AsArray().Count == 0, "cancelled dispatch returns to the candidate state");
        Console.WriteLine("Passed 4 dispatch start checks.");
        Check(dispatchStartReload.Dispatch("dispatch_bulk_end").Body!["result_dict_list"]!.AsArray().Count == 0, "dispatch bulk settlement accepts no tasks");
        dispatchStartReload.Dispatch("dispatch_start", arguments: dispatchStartArgs);
        Check(dispatchStartReload.Dispatch("dispatch_bulk_end").Body!["remove_user_dispatch_ids"]!.AsArray().Count == 0 && dispatchStartReload.Dispatch("login").Body!["user"]!["dispatch"]!["dispatch_list"]!.AsArray().Count == 1, "dispatch bulk settlement preserves running tasks");
        var expiredDispatchSeed = dispatchStartSeed.DeepClone();
        expiredDispatchSeed["dispatch"]!["dispatch_list"] = new JsonArray(new JsonObject { ["user_dispatch_id"] = 701L, ["dispatch_id"] = 7, ["end_time"] = "2000-01-01 00:00:00", ["user_unit_id_list"] = new JsonArray(JsonValue.Create(dispatchMemberId)) });
        var expiredDispatchServer = new OfflineServer(new JsonStateStore(directory + "-dispatch-expired"), expiredDispatchSeed.ToJsonString(), "offline://resources/");
        expiredDispatchServer.Dispatch("game_init");
        expiredDispatchServer.Dispatch("login");
        Check(expiredDispatchServer.Dispatch("dispatch_bulk_end").Status == 503 && expiredDispatchServer.Dispatch("login").Body!["user"]!["dispatch"]!["dispatch_list"]!.AsArray().Count == 1, "dispatch bulk settlement never discards finished tasks without rewards");
        Console.WriteLine("Passed 3 dispatch bulk boundary checks.");
    }
}
